CREATE TABLE training_programs (id TEXT PRIMARY KEY, reference_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, start_date TEXT, end_date TEXT, location TEXT, status TEXT NOT NULL DEFAULT 'planned', created_at TEXT NOT NULL);
CREATE TABLE training_companies (id TEXT PRIMARY KEY, training_program_id TEXT NOT NULL, company_name TEXT NOT NULL, participant_count INTEGER NOT NULL DEFAULT 0, unit_price REAL NOT NULL DEFAULT 1799, gross_hrdc_claim REAL NOT NULL DEFAULT 0, grant_status TEXT NOT NULL DEFAULT 'follow_up', rebate_status TEXT NOT NULL DEFAULT 'unused', rebate_profile TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(training_program_id) REFERENCES training_programs(id) ON DELETE CASCADE);
CREATE TABLE company_participants (id TEXT PRIMARY KEY, training_company_id TEXT NOT NULL, full_name TEXT NOT NULL, ic_number TEXT NOT NULL, application_status TEXT NOT NULL DEFAULT 'pending_application', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(training_company_id, ic_number), FOREIGN KEY(training_company_id) REFERENCES training_companies(id) ON DELETE CASCADE);
CREATE TABLE reporting_periods (id TEXT PRIMARY KEY, reporting_year INTEGER NOT NULL, reporting_month INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(reporting_year, reporting_month));
CREATE TABLE dashboard_summaries (id TEXT PRIMARY KEY, reporting_year INTEGER NOT NULL UNIQUE, total_training_revenue REAL NOT NULL DEFAULT 0, total_rebate_credit REAL NOT NULL DEFAULT 0, hrdc_paid_to_slx REAL NOT NULL DEFAULT 0, net_training_contribution REAL NOT NULL DEFAULT 0, rebate_credit_used REAL NOT NULL DEFAULT 0, unutilised_rebate_credit REAL NOT NULL DEFAULT 0, rebate_utilisation_percent REAL NOT NULL DEFAULT 0, number_of_trainings INTEGER NOT NULL DEFAULT 0, total_participants INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE monthly_training_performance (id TEXT PRIMARY KEY, reporting_period_id TEXT NOT NULL UNIQUE, training_revenue REAL NOT NULL DEFAULT 0, rebate_issued REAL NOT NULL DEFAULT 0, credit_used REAL NOT NULL DEFAULT 0, remaining_credit REAL NOT NULL DEFAULT 0, number_of_trainings INTEGER NOT NULL DEFAULT 0, net_contribution REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(reporting_period_id) REFERENCES reporting_periods(id));
CREATE TABLE credit_usage_categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE credit_usage_records (id TEXT PRIMARY KEY, reporting_period_id TEXT NOT NULL, category_id TEXT NOT NULL, amount_used REAL NOT NULL DEFAULT 0, usage_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(reporting_period_id, category_id));
CREATE INDEX idx_training_companies_program ON training_companies(training_program_id);
CREATE INDEX idx_company_participants_company ON company_participants(training_company_id);
